<?php
function BookingController(string $resource, ?int $id, array $part, string $method):void {
if($resource==='bookings'){
  $u=currentUser();
  if($method==='GET'&&$id===null){if($u['role']==='admin')$s=db()->query('SELECT b.*,e.title AS event_title FROM bookings b JOIN events e ON e.id=b.event_id ORDER BY b.id DESC');elseif($u['role']==='organiser'){$s=db()->prepare('SELECT b.*,e.title AS event_title FROM bookings b JOIN events e ON e.id=b.event_id WHERE e.organiser_id=? ORDER BY b.id DESC');$s->execute([$u['id']]);}else{$s=db()->prepare('SELECT b.*,e.title AS event_title FROM bookings b JOIN events e ON e.id=b.event_id WHERE b.user_id=? ORDER BY b.id DESC');$s->execute([$u['id']]);}reply(200,$s->fetchAll());}
  if($method==='GET'&&$id!==null){$s=db()->prepare('SELECT b.*,e.title AS event_title,e.organiser_id FROM bookings b JOIN events e ON e.id=b.event_id WHERE b.id=?');$s->execute([$id]);$b=$s->fetch();need((bool)$b,'Booking not found',404);need($u['role']==='admin'||(int)$b['user_id']===(int)$u['id']||($u['role']==='organiser'&&(int)$b['organiser_id']===(int)$u['id']),'Access denied',403);reply(200,$b);}
  if($method==='POST'&&$id===null){$d=body();requireFields($d,['event_id','quantity']);need(positive($d['event_id'])&&positive($d['quantity']),'Invalid quantity or event');$pdo=db();$pdo->beginTransaction();try{$e=getEvent((int)$d['event_id'],true);need((bool)$e,'Event not found',404);need($e['status']==='published','Event is unavailable');need(strtotime($e['event_date'])>time(),'Event already finished');need((int)$d['quantity']<=(int)$e['available'],'Not enough tickets',409);$s=$pdo->prepare('INSERT INTO bookings(user_id,event_id,quantity,total_amount) VALUES (?,?,?,?)');$s->execute([$u['id'],$e['id'],$d['quantity'],round($d['quantity']*$e['ticket_price'],2)]);$newId=(int)$pdo->lastInsertId();logAction((int)$u['id'],'booking.created',"Booking #$newId");$pdo->commit();reply(201,['id'=>$newId,'status'=>'confirmed','message'=>'Booking successful']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
  if($id!==null&&($method==='PATCH'||$method==='PUT'||$method==='DELETE')){$s=db()->prepare('SELECT * FROM bookings WHERE id=?');$s->execute([$id]);$b=$s->fetch();need((bool)$b,'Booking not found',404);need($u['role']==='admin'||(int)$u['id']===(int)$b['user_id'],'Access denied',403);need($b['status']==='confirmed','Booking already cancelled',409);if($method!=='DELETE'){$d=body();need(($d['status']??'')==='cancelled','Only cancellation is supported');}$s=db()->prepare("UPDATE bookings SET status='cancelled' WHERE id=?");$s->execute([$id]);logAction((int)$u['id'],'booking.cancelled',"Booking #$id");reply(200,['message'=>'Booking cancelled']);}
 }
}
